+                                                        throw new RuntimeException(e);
+                                                    }
+                                                }).takeWhile(bb -> bb != null)
+                                            ),
+                                            stream -> {
+                                                try {
+                                                    stream.close();
+                                                } catch (Exception e) {
+                                                    // Log or handle
+                                                }
+                                            }
+                                        )
+                                )
+                                .setBlockSizeLong((long) BLOCK_SIZE)
+                                .setMetadata(metadata)
+                                .setTags(tags);
